import type { AiMeta } from "@/lib/api-types";

export async function postJson<T>(url: string, body: unknown, timeoutMs = 30_000): Promise<T> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body), signal: ctrl.signal });
    if (!res.ok) throw new Error(`${url} returned ${res.status}`);
    return (await res.json()) as T;
  } finally {
    clearTimeout(timer);
  }
}

/** "generated by claude-sonnet-5-5 · 1,234 tokens · 2,310 ms" or "precomputed (demo)". */
export function metaLine(m: AiMeta | null | undefined): string {
  if (!m) return "";
  if (m.mode === "live" && m.usage) {
    const tok = (m.usage.inputTokens + m.usage.outputTokens).toLocaleString("en-US");
    return `generated by ${m.usage.model} · ${tok} tokens · ${m.usage.latencyMs.toLocaleString("en-US")} ms`;
  }
  return m.fallbackReason ? `precomputed (demo, live call ${m.fallbackReason.replace("_", " ")})` : "precomputed (demo)";
}
